package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen1Test {

    @Test
    public void testValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        JsonWriter result = jsonWriter.value(12345L);
        assertTrue(result instanceof JsonWriter);
    }

    @Test(expected = IOException.class)
    public void testValueIOException() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(false);
        jsonWriter.value(12345L);
    }

    @Test
    public void testValueNull() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.value(null);
        assertTrue(jsonWriter instanceof JsonWriter);
    }

    @Test
    public void testValueMinValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.value(Long.MIN_VALUE);
        assertTrue(jsonWriter instanceof JsonWriter);
    }

    @Test
    public void testValueMinValuePlusOne() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.value(Long.MIN_VALUE + 1);
        assertTrue(jsonWriter instanceof JsonWriter);
    }

    @Test
    public void testValueMaxValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.value(Long.MAX_VALUE);
        assertTrue(jsonWriter instanceof JsonWriter);
    }

    @Test
    public void testValueMaxValueMinusOne() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.value(Long.MAX_VALUE - 1);
        assertTrue(jsonWriter instanceof JsonWriter);
    }

    @Test
    public void testValueString() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.value("12345");
        assertTrue(jsonWriter instanceof JsonWriter);
    }

    @Test
    public void testValueBooleanTrue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.value(true);
        assertTrue(jsonWriter instanceof JsonWriter);
    }

    @Test
    public void testValueBooleanFalse() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.value(false);
        assertTrue(jsonWriter instanceof JsonWriter);
    }

    @Test
    public void testValueDouble() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.value(123.45);
        assertTrue(jsonWriter instanceof JsonWriter);
    }

    @Test
    public void testValueNumber() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.value(123);
        assertTrue(jsonWriter instanceof JsonWriter);
    }

    @Test
    public void testValueNullAfterWrite() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.writeDeferredName();
        jsonWriter.beforeValue(false);
        jsonWriter.out.write("null");
        jsonWriter.value(null);
        assertTrue(jsonWriter instanceof JsonWriter);
    }
}
